mapper.select:
SELECT Id, DeviceID, Name, Tem, Hum, MAC, UpdateTime, ElectricEnergy, NodeID, Workshop FROM RSWS_TempMonitor
AND DeviceID = #{deviceId}
AND Name LIKE '%' + #{name} + '%'
AND Workshop = '114_空调水机主机'
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
ORDER BY
Tem Hum ElectricEnergy UpdateTime DeviceID Name UpdateTime
ASC DESC
ORDER BY UpdateTime DESC

SELECT COUNT(DISTINCT DeviceID)
FROM RSWS_TempMonitor

    AND Workshop = '114_空调水机主机'

        AND UpdateTime >= #{startTime}


        AND UpdateTime <= #{endTime}

WITH LatestDeviceData AS ( SELECT DeviceID, Tem, Hum, ElectricEnergy, UpdateTime, Workshop, ROW_NUMBER() OVER (PARTITION BY DeviceID ORDER BY UpdateTime DESC) as rn FROM RSWS_TempMonitor
AND Workshop = #{workshop}
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) SELECT AVG(Tem) as avgTemperature, MIN(Tem) as minTemperature, MAX(Tem) as maxTemperature, AVG(Hum) as avgHumidity, MIN(Hum) as minHumidity, MAX(Hum) as maxHumidity, SUM(ElectricEnergy) as totalElectricEnergy, AVG(ElectricEnergy) as avgElectricEnergy FROM LatestDeviceData WHERE rn = 1

SELECT TOP(#{limit}) Id, DeviceID, Name, Tem, Hum, MAC, UpdateTime, ElectricEnergy, NodeID, Workshop FROM RSWS_TempMonitor
ElectricEnergy IS NOT NULL AND ElectricEnergy > 0 AND Workshop = '114_空调水机主机'
AND DeviceID = #{deviceId}
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
ORDER BY UpdateTime DESC

WITH HourlyBoundaries AS ( -- 生成时间范围内的每个小时边界 SELECT DATEADD(HOUR, DATEDIFF(HOUR, 0, #{startTime} DATEADD(DAY, -1, GETDATE()) ) + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, 0) as HourStart, DATEADD(HOUR, DATEDIFF(HOUR, 0, #{startTime} DATEADD(DAY, -1, GETDATE()) ) + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)), 0) as HourEnd FROM ( SELECT TOP ( DATEDIFF(HOUR, #{startTime} DATEADD(DAY, -1, GETDATE()), #{endTime} GETDATE() ) + 1 ) 1 as num FROM RSWS_TempMonitor ) Numbers ), DeviceHourData AS ( -- 为每个设备和每个小时获取开始和结束时间的最近记录 SELECT h.HourStart, h.HourEnd, tm.DeviceID, tm.Name, tm.Workshop, -- 小时开始时间以后的最近记录 (SELECT TOP 1 ElectricEnergy FROM RSWS_TempMonitor t1 WHERE t1.DeviceID = tm.DeviceID AND t1.Workshop = '114_空调水机主机' AND t1.ElectricEnergy IS NOT NULL AND t1.UpdateTime >= h.HourStart ORDER BY t1.UpdateTime ASC) as StartEnergy, (SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor t1 WHERE t1.DeviceID = tm.DeviceID AND t1.Workshop = '114_空调水机主机' AND t1.ElectricEnergy IS NOT NULL AND t1.UpdateTime >= h.HourStart ORDER BY t1.UpdateTime ASC) as StartTime, -- 结束时间记录：如果是最新小时则用最新记录，否则用小时结束时间以后的最近记录 CASE WHEN h.HourStart = (SELECT MAX(HourStart) FROM HourlyBoundaries) THEN (SELECT TOP 1 ElectricEnergy FROM RSWS_TempMonitor t2 WHERE t2.DeviceID = tm.DeviceID AND t2.Workshop = '114_空调水机主机' AND t2.ElectricEnergy IS NOT NULL AND t2.UpdateTime <= h.HourEnd ORDER BY t2.UpdateTime DESC) ELSE (SELECT TOP 1 ElectricEnergy FROM RSWS_TempMonitor t2 WHERE t2.DeviceID = tm.DeviceID AND t2.Workshop = '114_空调水机主机' AND t2.ElectricEnergy IS NOT NULL AND t2.UpdateTime >= h.HourEnd ORDER BY t2.UpdateTime ASC) END as EndEnergy, CASE WHEN h.HourStart = (SELECT MAX(HourStart) FROM HourlyBoundaries) THEN (SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor t2 WHERE t2.DeviceID = tm.DeviceID AND t2.Workshop = '114_空调水机主机' AND t2.ElectricEnergy IS NOT NULL AND t2.UpdateTime <= h.HourEnd ORDER BY t2.UpdateTime DESC) ELSE (SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor t2 WHERE t2.DeviceID = tm.DeviceID AND t2.Workshop = '114_空调水机主机' AND t2.ElectricEnergy IS NOT NULL AND t2.UpdateTime >= h.HourEnd ORDER BY t2.UpdateTime ASC) END as EndTime FROM HourlyBoundaries h CROSS JOIN ( SELECT DISTINCT DeviceID, Name, Workshop FROM RSWS_TempMonitor WHERE Workshop = '114_空调水机主机' AND ElectricEnergy IS NOT NULL
AND DeviceID = #{deviceId}
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) tm ) SELECT DeviceID as deviceId, Name as name, Workshop as workshop, HourStart as hour, CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE 0 END as energyConsumption, StartEnergy as startEnergy, EndEnergy as endEnergy, StartTime as startTime, EndTime as endTime FROM DeviceHourData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy ORDER BY HourStart, DeviceID

WITH HourlyBoundaries AS ( -- 生成时间范围内的每个小时边界 SELECT DATEADD(HOUR, DATEDIFF(HOUR, 0, #{startTime} DATEADD(DAY, -1, GETDATE()) ) + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, 0) as HourStart, DATEADD(HOUR, DATEDIFF(HOUR, 0, #{startTime} DATEADD(DAY, -1, GETDATE()) ) + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)), 0) as HourEnd FROM ( SELECT TOP ( DATEDIFF(HOUR, #{startTime} DATEADD(DAY, -1, GETDATE()), #{endTime} GETDATE() ) + 1 ) 1 as num FROM RSWS_TempMonitor ) Numbers ), DeviceHourData AS ( -- 为每个设备和每个小时获取开始和结束时间的记录 SELECT h.HourStart, h.HourEnd, tm.DeviceID, tm.Name, tm.Workshop, -- 小时开始时间以后的最近记录 (SELECT TOP 1 ElectricEnergy FROM RSWS_TempMonitor t1 WHERE t1.DeviceID = tm.DeviceID AND t1.Workshop = '114_空调水机主机' AND t1.ElectricEnergy IS NOT NULL AND t1.UpdateTime >= h.HourStart ORDER BY t1.UpdateTime ASC) as StartEnergy, (SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor t1 WHERE t1.DeviceID = tm.DeviceID AND t1.Workshop = '114_空调水机主机' AND t1.ElectricEnergy IS NOT NULL AND t1.UpdateTime >= h.HourStart ORDER BY t1.UpdateTime ASC) as StartTime, -- 修改：获取每小时结束后最早的电能数据 (SELECT TOP 1 ElectricEnergy FROM RSWS_TempMonitor t2 WHERE t2.DeviceID = tm.DeviceID AND t2.Workshop = '114_空调水机主机' AND t2.ElectricEnergy IS NOT NULL AND t2.UpdateTime >= h.HourEnd -- 改为大于等于小时结束时间 ORDER BY t2.UpdateTime ASC) as EndEnergy, -- 按时间升序取第一条 (SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor t2 WHERE t2.DeviceID = tm.DeviceID AND t2.Workshop = '114_空调水机主机' AND t2.ElectricEnergy IS NOT NULL AND t2.UpdateTime >= h.HourEnd ORDER BY t2.UpdateTime ASC) as EndTime FROM HourlyBoundaries h CROSS JOIN ( SELECT DISTINCT DeviceID, Name, Workshop FROM RSWS_TempMonitor WHERE Workshop = '114_空调水机主机' AND ElectricEnergy IS NOT NULL
AND DeviceID = #{deviceId}
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) tm ) SELECT DeviceID as deviceId, Name as name, Workshop as workshop, HourStart as hour, CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE 0 END as energyConsumption, StartEnergy as startEnergy, EndEnergy as endEnergy, StartTime as startTime, EndTime as endTime FROM DeviceHourData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy ORDER BY HourStart, DeviceID
